#!/usr/bin/env bash
# Self-test for attribution-guard.sh: builds a throwaway repo with git commit-tree (no hooks run, nothing is
# committed to this repository) and checks that every marker fails the guard and clean text passes.
# Usage: attribution-guard-selftest.sh   (run from anywhere; needs git and bash)
set -u -o pipefail
GUARD="$(cd "$(dirname "$0")" && pwd)/attribution-guard.sh"
[ -f "$GUARD" ] || { echo "guard script not found: $GUARD"; exit 2; }
W=$(mktemp -d) || exit 2
trap 'rm -rf "$W"' EXIT
cd "$W" && git init -q . || exit 2

JN='Jordan Allen Lewis'; JE='42820601+jordanallenlewis@users.noreply.github.com'
TREE=$(git hash-object -t tree -w /dev/null)
# marker strings are assembled from parts so this file itself carries none of them
CS="Claude-""Session"; AG="Ag""ent"; CO="Co-authored""-by"; CC="Claude"" Code"

mk() { # message parent [author-name author-email committer-name committer-email] -> sha
  local m=$1 p=$2 an=${3:-$JN} ae=${4:-$JE} cn=${5:-$JN} ce=${6:-$JE}
  GIT_AUTHOR_NAME=$an GIT_AUTHOR_EMAIL=$ae GIT_COMMITTER_NAME=$cn GIT_COMMITTER_EMAIL=$ce \
    git commit-tree "$TREE" -p "$p" -F - <<< "$m"
}
ROOT=$(GIT_AUTHOR_NAME=$JN GIT_AUTHOR_EMAIL=$JE GIT_COMMITTER_NAME=$JN GIT_COMMITTER_EMAIL=$JE git commit-tree "$TREE" -m "root") || exit 2
BASE=$(mk "base" "$ROOT")

pass=0; failn=0
run() { # name expected-exit(0|1|2) event base head [title body author headref]
  local name=$1 want=$2 ev=$3 base=$4 head=$5 title=${6:-} body=${7:-} author=${8:-jordanallenlewis} hr=${9:-feature}
  EVENT=$ev BASE=$base HEAD=$head TITLE=$title BODY=$body PR_AUTHOR=$author HEAD_REF=$hr bash "$GUARD" >"$W/out.txt" 2>&1
  local rc=$?
  if [ "$rc" = "$want" ]; then
    echo "ok   $name (exit $rc)"; pass=$((pass+1))
  else
    echo "FAIL $name (exit $rc, wanted $want)"; sed 's/^/     | /' "$W/out.txt"; failn=$((failn+1))
  fi
}
pr() { run "$1" "$2" pull_request "$BASE" "$3" "${4:-}" "${5:-}" "${6:-jordanallenlewis}" "${7:-feature}"; }
msgcase() { local h; h=$(mk "$2" "$BASE"); pr "$1" "$3" "$h"; }

echo "== must pass =="
msgcase "clean commit" "Fix the retry loop" 0
msgcase "product mention: grades servers for Claude clients" "Grade servers for Claude clients and for $CC users" 0
pr "clean title and body, product mention" 0 "$(mk "Docs" "$BASE")" "Works with $CC" "Grades servers for Claude clients"
H=$(mk "Squash merge" "$BASE" "$JN" "$JE" "GitHub" "noreply@github.com"); pr "GitHub web-merge committer" 0 "$H"
H=$(mk "Bump x" "$BASE" "dependabot[bot]" "49699333+dependabot[bot]@users.noreply.github.com" "GitHub" "noreply@github.com")
pr "dependabot PR keeps its bot identity" 0 "$H" "Bump x" "" "dependabot[bot]" "dependabot/npm/x"
H=$(mk "Fleet commit" "$BASE" "Jordan Lewis" "$JE" "Jordan Lewis" "$JE"); run "push: fleet bot name Jordan Lewis, Jordan email" 0 push "$BASE" "$H"
H=$(mk "Direct push, clean" "$BASE"); run "push: clean commit" 0 push "$BASE" "$H"
run "push: zero before sha (new branch), clean head" 0 push 0000000000000000000000000000000000000000 "$H"

echo "== markers that blocked before this change =="
msgcase "$CS trailer" "x"$'\n\n'"$CS: abc" 1
msgcase "claude.ai/code link" "x"$'\n\n'"https://claude.ai/code/session_1" 1
msgcase "claude.com/claude-code link" "x"$'\n\n'"see https://claude.com/claude-code" 1
msgcase "$AG trailer" "x"$'\n\n'"$AG: Hannah" 1
msgcase "indented $AG trailer" "x"$'\n\n'"   $AG: Hannah" 1
msgcase "$CO trailer (Jordan's own)" "x"$'\n\n'"$CO: Jordan Allen Lewis <$JE>" 1
msgcase "Generated with [$CC]" "x"$'\n\n'"Generated with [$CC](https://claude.com/claude-code)" 1
msgcase "Requested-by trailer" "x"$'\n\n'"Requested-by: Maya" 1
pr "title: $AG trailer line" 1 "$(mk "ok" "$BASE")" "$CS: x"
pr "body: claude.ai/code link" 1 "$(mk "ok" "$BASE")" "ok" "made at https://claude.ai/code/x"
pr "agent email author" 1 "$(mk "ok" "$BASE" "$JN" "hq-sealmark@agent.local")"

echo "== markers added in this change =="
msgcase "lone robot emoji" "Fix thing "$'\xf0\x9f\xa4\x96' 1
msgcase "Generated by Claude" "x"$'\n\n'"Generated by Claude" 1
msgcase "Signed-off-by: Claude" "x"$'\n\n'"Signed-off-by: Claude <noreply@x.test>" 1
pr "title: robot emoji" 1 "$(mk "ok" "$BASE")" $'\xf0\x9f\xa4\x96 add thing'
pr "body: Generated by Claude" 1 "$(mk "ok" "$BASE")" "ok" "Generated by Claude"
pr "author NAME is Claude, email Jordan's" 1 "$(mk "ok" "$BASE" "Claude" "$JE" "$JN" "$JE")"
pr "committer NAME is an agent, email Jordan's" 1 "$(mk "ok" "$BASE" "$JN" "$JE" "hq-sealmark" "$JE")"
pr "author name is not Jordan Allen Lewis" 1 "$(mk "ok" "$BASE" "Someone Else" "$JE" "$JN" "$JE")"
pr "committer name is not Jordan Allen Lewis" 1 "$(mk "ok" "$BASE" "$JN" "$JE" "Someone Else" "$JE")"
pr "committer GitHub with a non-GitHub email" 1 "$(mk "ok" "$BASE" "$JN" "$JE" "GitHub" "$JE")"

echo "== direct pushes and merged messages =="
H=$(mk "x"$'\n\n'"$CS: abc" "$BASE"); run "push: $CS trailer in the pushed commit" 1 push "$BASE" "$H"
H=$(mk "Squash: Add thing (#9)"$'\n\n'"* wip"$'\n\n'"$AG: Hannah" "$BASE"); run "push: merged squash message with $AG trailer" 1 push "$BASE" "$H"
H=$(mk "ok" "$BASE" "Claude" "$JE" "$JN" "$JE"); run "push: author name Claude" 1 push "$BASE" "$H"
H=$(mk "ok" "$BASE" "$JN" "someone@example.com" "$JN" "someone@example.com"); run "push: foreign email" 1 push "$BASE" "$H"
H1=$(mk "x"$'\n\n'"$CS: abc" "$BASE"); H2=$(mk "clean tip" "$H1"); run "push: bad commit in the middle of the range" 1 push "$BASE" "$H2"
H=$(mk "x"$'\n\n'"$CS: abc" "$BASE"); run "push: zero before sha, bad head" 1 push 0000000000000000000000000000000000000000 "$H"
run "push: empty before sha, bad head" 1 push "" "$H"

echo "== pushed dependabot merges and large text =="
DB='49699333+dependabot[bot]@users.noreply.github.com'
COB="$CO: dependabot[bot] <$DB>"
H=$(mk "Bump x (#18)"$'\n\n'"Signed-off-by: dependabot[bot] <support@github.com>"$'\n'"$COB" "$BASE" "dependabot[bot]" "$DB" "GitHub" "noreply@github.com")
run "push: dependabot web squash with GitHub's co-author line for the bot" 0 push "$BASE" "$H"
H=$(mk "Bump y (#19)" "$BASE" "renovate[bot]" "29139614+renovate[bot]@users.noreply.github.com" "GitHub" "noreply@github.com")
run "push: renovate web squash" 0 push "$BASE" "$H"
H=$(mk "Bump z (#20)"$'\n\n'"* bump"$'\n\n'"$COB" "$BASE" "$JN" "$JE" "GitHub" "noreply@github.com")
run "push: Jordan's squash of a grouped dependabot PR (bot co-author line only)" 0 push "$BASE" "$H"
H=$(mk "Bump x"$'\n\n'"$CO: Someone Else <someone@example.com>" "$BASE" "dependabot[bot]" "$DB" "GitHub" "noreply@github.com")
run "push: dependabot squash with a co-author line naming someone else" 1 push "$BASE" "$H"
H=$(mk "Bump x"$'\n\n'"$COB"$'\n'"$CO: $CC <noreply@anthropic.com>" "$BASE" "dependabot[bot]" "$DB" "GitHub" "noreply@github.com")
run "push: bot co-author line plus a second co-author line" 1 push "$BASE" "$H"
H=$(mk "Bump x" "$BASE" "dependabot[bot]" "$DB" "$JN" "$JE")
run "push: authored as dependabot, committer is not GitHub" 1 push "$BASE" "$H"
H=$(mk "Bump x" "$BASE" "dependabot[bot]" "$DB" "GitHub" "someone@example.com")
run "push: authored as dependabot, foreign committer email" 1 push "$BASE" "$H"
H=$(mk "Bump x" "$BASE" "dependabot[bot]" "evil+dependabot[bot]@users.noreply.github.com" "GitHub" "noreply@github.com")
run "push: look-alike dependabot author email" 1 push "$BASE" "$H"
H=$(mk "Bump x"$'\n\n'"$CS: abc" "$BASE" "dependabot[bot]" "$DB" "GitHub" "noreply@github.com")
run "push: dependabot identity does not excuse a marker in the message" 1 push "$BASE" "$H"
PAD=$(head -c 300000 /dev/zero | tr '\0' 'a')
H=$(mk "x"$'\n\n'"$CS: abc"$'\n\n'"$PAD" "$BASE"); run "push: trailer near the top of a ~300 KB message" 1 push "$BASE" "$H"
pr "PR: trailer near the top of a ~300 KB message" 1 "$H"
H=$(mk "ok"$'\n\n'"$PAD" "$BASE"); run "push: ~300 KB clean message" 0 push "$BASE" "$H"

# GNU grep under a UTF-8 locale treats a line holding an invalid byte as non-matching, so the push-only strip of the bot
# co-author line (grep -Ev) dropped such a line from the scanned text and a marker on it passed. The guard now uses grep -a.
# git commit-tree re-encodes a stray byte, so these commits are written raw with an "encoding UTF-8" header, which makes git log emit the bytes untouched.
mkraw() { # trailer-line-with-a-0xff-byte -> sha
  printf 'tree %s\nparent %s\nauthor %s <%s> 1700000000 +0000\ncommitter %s <%s> 1700000000 +0000\nencoding UTF-8\n\nx\n\n%s \xff\n' "$TREE" "$BASE" "$JN" "$JE" "$JN" "$JE" "$1" | git hash-object -t commit -w --stdin
}
H=$(mkraw "$AG: Hannah"); LC_ALL=C.UTF-8 run "push: $AG trailer line holding a non-UTF-8 byte (UTF-8 locale)" 1 push "$BASE" "$H"
H=$(mkraw "$CS: abc"); LC_ALL=C.UTF-8 run "push: $CS trailer line holding a non-UTF-8 byte (UTF-8 locale)" 1 push "$BASE" "$H"

echo "== convergence step 1: Signed-off-by naming an agent, and agent/ai/bot names next to _ or a digit =="
msgcase "PR: Signed-off-by: hq-x" "x"$'\n\n'"Signed-off-by: hq-x <x@example.com>" 1
msgcase "PR: Signed-off-by: Trinity Agent" "x"$'\n\n'"Signed-off-by: Trinity Agent <x@example.com>" 1
msgcase "PR: Signed-off-by with a space before the colon" "x"$'\n\n'"Signed-off-by : Claude <x@example.com>" 1
H=$(mk "x"$'\n\n'"Signed-off-by: Trinity Agent <x@example.com>" "$BASE"); run "push: Signed-off-by: Trinity Agent" 1 push "$BASE" "$H"
H=$(mk "x"$'\n\n'"Signed-off-by: build agent <x@example.com>" "$BASE"); run "push: Signed-off-by: build agent" 1 push "$BASE" "$H"
H=$(mk "x"$'\n\n'"Signed-off-by: Jordan Allen Lewis <$JE>" "$BASE"); run "push: Signed-off-by: Jordan (must pass)" 0 push "$BASE" "$H"
for nm in build_agent agent2 Agent_Smith ci_bot ai_helper gpt_helper; do
  H=$(mk "ok" "$BASE" "$nm" "$JE" "$JN" "$JE"); run "push: author name $nm" 1 push "$BASE" "$H"
  H=$(mk "ok" "$BASE" "$JN" "$JE" "$nm" "$JE"); run "push: committer name $nm" 1 push "$BASE" "$H"
  pr "PR by someone else: author name $nm" 1 "$(mk "ok" "$BASE" "$nm" "$JE" "$JN" "$JE")" "t" "b" someone
done
for nm in Agency "Reagent Smith" "Abbott Botha" "Sai Kumar" "Tai Mai"; do
  H=$(mk "ok" "$BASE" "$nm" "$JE" "$nm" "$JE"); run "push: name $nm (must pass)" 0 push "$BASE" "$H"
  pr "PR by someone else: author name $nm (must pass)" 0 "$(mk "ok" "$BASE" "$nm" "$JE" "$nm" "$JE")" "t" "b" someone
done

echo "== fail closed =="
H=$(mk "x"$'\n\n'"$CS: abc" "$BASE")
run "unreachable base, bad commit (was rc=0 before)" 2 pull_request deadbeefdeadbeefdeadbeefdeadbeefdeadbeef "$H"
# force-push: a push whose BASE is not in the checkout judges every commit reachable from HEAD
# (the old "unreachable base on push" case, exit 2, is replaced by the two cases below: a marker in the history now fails with exit 1)
UNREACH=deadbeefdeadbeefdeadbeefdeadbeefdeadbeef
CLEAN=$(mk "clean after rewrite" "$BASE"); run "force-push: unreachable base, clean full history" 0 push "$UNREACH" "$CLEAN"
grep -q "base unreachable (force-push): judging full history, 3 commits" "$W/out.txt" && { echo "ok   force-push: notice names 3 commits"; pass=$((pass+1)); } || { echo "FAIL force-push: notice missing"; sed 's/^/     | /' "$W/out.txt"; failn=$((failn+1)); }
OLDBAD=$(mk "x"$'\n\n'"$CS: abc" "$ROOT"); NEWBAD=$(mk "clean tip" "$OLDBAD"); run "force-push: unreachable base, old commit carries a marker" 1 push "$UNREACH" "$NEWBAD"
run "force-push: unreachable base, marker in the head commit" 1 push "$UNREACH" "$H"
run "force-push: unreachable base, old commit has a foreign email" 1 push "$UNREACH" "$(mk ok "$(mk old "$ROOT" "$JN" someone@example.com "$JN" someone@example.com)")"
git update-ref refs/heads/shallowsrc "$CLEAN"
SH=$(mktemp -d) && git clone -q --depth 1 --branch shallowsrc "file://$W" "$SH/c" 2>/dev/null && SHH=$(git -C "$SH/c" rev-parse HEAD) || SHH=
if [ -n "$SHH" ]; then
  (cd "$SH/c" && EVENT=push BASE=$UNREACH HEAD=$SHH bash "$GUARD" >"$W/out.txt" 2>&1); rc=$?
  if [ "$rc" = 2 ]; then echo "ok   force-push: shallow checkout dies (exit 2)"; pass=$((pass+1)); else echo "FAIL force-push: shallow checkout (exit $rc, wanted 2)"; failn=$((failn+1)); fi
else echo "FAIL force-push: could not build a shallow clone"; failn=$((failn+1)); fi
rm -rf "$SH"
run "pull request with an unreachable base still dies" 2 pull_request "$UNREACH" "$CLEAN"
run "empty range (BASE == HEAD)" 2 pull_request "$BASE" "$BASE"
run "empty base on a pull request" 2 pull_request "" "$H"
run "missing head" 2 pull_request "$BASE" ""
run "unknown head" 2 pull_request "$BASE" deadbeefdeadbeefdeadbeefdeadbeefdeadbeef
run "unknown event" 2 tag "$BASE" "$H"

echo
echo "attribution-guard self-test: $pass passed, $failn failed"
[ "$failn" = 0 ]
